issues:
The SEO implementation does not add Open Graph tags (og:title, og:description, og:url, og:type) and canonical link elements to each prerendered page. The test suite checks for these metadata tags to ensure each page meets requirements R6-R8, but they are missing from the generated HTML.
Proven by this test, which fails on the current code:
/*
REPRO issue for SEO meta tags
The SEO implementation does not add Open Graph tags (og:title, og:description, og:url, og:type) and canonical link elements to each prerendered page.
*/

/** @jest-environment jsdom */
import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

describe('REPRO: Open Graph meta tags and canonical link are missing from prerendered pages', () => {
  const ROOT = path.resolve(__dirname, '..', '..');
  const DIST = path.join(ROOT, 'dist');

  beforeAll(() => {
    // Build the site to ensure dist files are up to date
    execSync('npm run build', { cwd: ROOT, stdio: 'ignore' });
  });

  test('Open Graph tags and canonical link exist in engagements page', () => {
    const htmlPath = path.join(DIST, 'engagements', 'index.html');
    if (!fs.existsSync(htmlPath)) {
      throw new Error(`File not found: ${htmlPath}`);
    }
    const html = fs.readFileSync(htmlPath, 'utf8');
    const doc = new DOMParser().parseFromString(html, 'text/html');
    expect(doc.querySelector('meta[property=\"og:title\"]')).not.toBeNull();
    expect(doc.querySelector('meta[property=\"og:description\"]')).not.toBeNull();
    expect(doc.querySelector('meta[property=\"og:url\"]')).not.toBeNull();
    expect(doc.querySelector('meta[property=\"og:type\"]')).not.toBeNull();
    expect(doc.querySelector('link[rel=\"canonical\"]')).not.toBeNull();
  });
});
